1	package credit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11	)
12	
13	// recordVersion 是当前记录文件格式版本。
14	const recordVersion = 1
15	
16	// fileData 是记录文件的磁盘格式。
17	type fileData struct {
18		Version       int            `json:"version"`
19		Courses       []*Course      `json:"courses"`
20		Students      []*Student     `json:"students"`
21		Requirements  []*Requirement `json:"requirements"`
22		Enrollments   []*Enrollment  `json:"enrollments"`
23		Waivers       []*Waiver      `json:"waivers"`
24		NextResultSeq int            `json:"nextResultSeq"`
25	}
26	
27	// Load 从 path 读取记录。
28	//
29	// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
30	// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
31	// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
32	// 空文件同样视为损坏，而不是空记录。
33	//
34	// 整份文件必须只含一条完整记录：记录前后允许空白（空格、制表符、换行、
35	// 回车），但完整记录结束后只要还有任何内容——多出的右花括号或右方括号、
36	// 拼接的第二段 JSON、普通文字或没写完的 JSON 片段——都判为损坏并拒绝读取，
37	// 绝不依据已读到的前半条记录继续办理业务。
38	//
39	// 同一个 JSON 对象内的字段名称也只能出现一次：无论重复的是学分、学生编号
40	// 还是其他字段，也无论两个值是否相同，整份文件都判为损坏。规则同时适用于
41	// 最外层对象与其中的每条记录，字段名以 JSON 解码后的文字比较（直接写出与
42	// Unicode 转义同名仍算重复）；限制只针对同一对象，不同记录各自携带同名字段
43	// 是正常结构，字符串值里提到字段名不算重复。
44	func Load(path string) (s *Store, existed bool, err error) {
45		f, err := os.Open(path)
46		if err != nil {
47			if errors.Is(err, os.ErrNotExist) {
48				return NewStore(), false, nil
49			}
50			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
51		}
52		defer f.Close()
53	
54		fi, err := f.Stat()
55		if err != nil {
56			return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
57		}
58		if fi.Size() == 0 {
59			return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
60		}
61	
62		raw, err := io.ReadAll(f)
63		if err != nil {
64			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
65		}
66	
67		// 先在 token 流上检查同一 JSON 对象内是否出现重复字段名。标准库直接
68		// 解进结构体时会用后一个重复键静默覆盖前一个（例如课程写了两个
69		// credit，4 会被 9 悄悄顶替），这样的记录无法明确说明字段归属，必须
70		// 整份判为损坏，绝不能据此核对或办理。仅扫描第一份完整值，其后内容
71		// 仍由下方的“完整记录之后不得有多余内容”检查处理。
72		var dupErr *duplicateFieldError
73		if err := scanDuplicateKeys(bytes.NewReader(raw)); errors.As(err, &dupErr) {
74			return nil, true, fmt.Errorf(
75				"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 重复出现，字段归属无法确定），未做任何修改",
76				path, dupErr.field)
77		}
78	
79		var data fileData
80		dec := json.NewDecoder(bytes.NewReader(raw))
81		dec.DisallowUnknownFields()
82		if err := dec.Decode(&data); err != nil {
83			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
84		}
85		// 完整记录之后必须只剩下空白：再解一条原始 JSON，仅 io.EOF 表示记录后
86		// 别无他物。不能用 dec.More() 判断——它只向前看“值起始”标记，记录后
87		// 多出的右花括号/右方括号会让 More() 直接返回 false 而被漏掉。再次
88		// Decode 能覆盖全部情形：成功读到值说明后面拼接了第二段 JSON；返回
89		// 语法错误或 unexpected EOF 说明尾部有孤立括号、普通文字或未写完的
90		// 片段。这些一律视为文件损坏。
91		var extra json.RawMessage
92		switch err := dec.Decode(&extra); {
93		case errors.Is(err, io.EOF):
94			// 唯一一份完整记录之后只有空白，符合格式。
95		case err == nil:
96			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后还拼接了其他 JSON 数据），未做任何修改", path)
97		default:
98			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后仍有无法解析的多余内容），未做任何修改", path)
99		}
100	
101		s = NewStore()
102		if err := s.loadData(&data); err != nil {
103			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
104		}
105		return s, true, nil
106	}
107	
108	// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
109	func (s *Store) loadData(d *fileData) error {
110		if d.Version != recordVersion {
111			return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
112		}
113	
114		// 课程
115		for _, c := range d.Courses {
116			if c == nil {
117				return errors.New("存在空的课程记录")
118			}
119			if c.ID == "" {
120				return errors.New("存在没有编号的课程")
121			}
122			if c.Name == "" {
123				return fmt.Errorf("课程 %s 没有名称", c.ID)
124			}
125			if c.Credit <= 0 {
126				return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
127			}
128			if _, dup := s.courseByID[c.ID]; dup {
129				return fmt.Errorf("课程编号 %s 重复", c.ID)
130			}
131			s.courses = append(s.courses, c)
132			s.courseByID[c.ID] = c
133		}
134	
135		// 学生
136		for _, st := range d.Students {
137			if st == nil || st.ID == "" {
138				return errors.New("存在没有编号的学生记录")
139			}
140			if _, dup := s.studentByID[st.ID]; dup {
141				return fmt.Errorf("学生编号 %s 重复", st.ID)
142			}
143			s.students = append(s.students, st)
144			s.studentByID[st.ID] = st
145		}
146	
147		// 要求
148		for _, r := range d.Requirements {
149			if r == nil {
150				return errors.New("存在空的课程要求记录")
151			}
152			if r.StudentID == "" || r.ID == "" {
153				return errors.New("存在缺少学生编号或要求编号的课程要求")
154			}
155			if _, ok := s.studentByID[r.StudentID]; !ok {
156				return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
157			}
158			if _, ok := s.courseByID[r.CourseID]; !ok {
159				return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
160					r.StudentID, r.ID, r.CourseID)
161			}
162			key := reqKey(r.StudentID, r.ID)
163			if _, dup := s.reqByKey[key]; dup {
164				return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
165			}
166			dk := dupKey(r.StudentID, r.CourseID)
167			if other, dup := s.reqByDup[dk]; dup {
168				return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
169					r.StudentID, r.CourseID, other, r.ID)
170			}
171			s.requirements = append(s.requirements, r)
172			s.reqByKey[key] = r
173			s.reqByDup[dk] = r.ID
174		}
175	
176		// 修读
177		usedSeq := map[int]bool{}
178		for _, e := range d.Enrollments {
179			if e == nil {
180				return errors.New("存在空的修读记录")
181			}
182			if e.StudentID == "" || e.ID == "" {
183				return errors.New("存在缺少学生编号或修读编号的修读记录")
184			}
185			if _, ok := s.studentByID[e.StudentID]; !ok {
186				return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
187			}
188			r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
189			if r == nil {
190				return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
191					e.StudentID, e.ID, e.ReqID)
192			}
193			if e.Term == "" {
194				return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
195			}
196			switch e.Result {
197			case Enrolled, Passed, Failed:
198			default:
199				return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
200			}
201			if e.Result == Enrolled {
202				if e.ResultSeq != 0 {
203					return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
204				}
205			} else {
206				if e.ResultSeq <= 0 {
207					return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
208				}
209				if usedSeq[e.ResultSeq] {
210					return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
211				}
212				usedSeq[e.ResultSeq] = true
213			}
214			key := reqKey(e.StudentID, e.ID)
215			if _, dup := s.enrByKey[key]; dup {
216				return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
217			}
218			s.enrollments = append(s.enrollments, e)
219			s.enrByKey[key] = e
220		}
221	
222		// 免修（被拒绝的申请允许指向当时不存在的要求）
223		approvedReq := map[string]string{} // student+"\x00"+req -> waiverID
224		for _, w := range d.Waivers {
225			if w == nil {
226				return errors.New("存在空的免修记录")
227			}
228			if w.StudentID == "" || w.ID == "" {
229				return errors.New("存在缺少学生编号或免修编号的免修记录")
230			}
231			if _, ok := s.studentByID[w.StudentID]; !ok {
232				return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
233			}
234			switch w.Status {
235			case WaiverApproved, WaiverRejected, WaiverRevoked:
236			default:
237				return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
238			}
239			if w.Status == WaiverApproved {
240				if w.Basis == "" {
241					return fmt.Errorf("有效免修 %s 缺少依据", w.ID)
242				}
243				rk := reqKey(w.StudentID, w.ReqID)
244				if s.reqByKey[rk] == nil {
245					return fmt.Errorf("有效免修 %s 指向不存在的要求 %s", w.ID, w.ReqID)
246				}
247				if other, dup := approvedReq[rk]; dup {
248					return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
249						w.StudentID, w.ReqID, other, w.ID)
250				}
251				approvedReq[rk] = w.ID
252			}
253			key := reqKey(w.StudentID, w.ID)
254			if _, dup := s.waiverByKey[key]; dup {
255				return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
256			}
257			s.waivers = append(s.waivers, w)
258			s.waiverByKey[key] = w
259		}
260	
261		if d.NextResultSeq < 0 {
262			return errors.New("结果提交序号计数器为负数")
263		}
264		for seq := range usedSeq {
265			if seq > d.NextResultSeq {
266				return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
267			}
268		}
269		s.nextResultSeq = d.NextResultSeq
270		return nil
271	}
272	
273	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
274	// 避免写到一半时损坏原文件。
275	func (s *Store) Save(path string) (err error) {
276		data := fileData{
277			Version:       recordVersion,
278			Courses:       s.courses,
279			Students:      s.students,
280			Requirements:  s.requirements,
281			Enrollments:   s.enrollments,
282			Waivers:       s.waivers,
283			NextResultSeq: s.nextResultSeq,
284		}
285		buf, err := json.MarshalIndent(&data, "", "  ")
286		if err != nil {
287			return fmt.Errorf("无法序列化记录：%w", err)
288		}
289		buf = append(buf, '\n')
290	
291		dir := filepath.Dir(path)
292		if dir == "" {
293			dir = "."
294		}
295		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
296		if err != nil {
297			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
298		}
299		tmpName := tmp.Name()
300		defer func() {
301			if err != nil {
302				tmp.Close()
303				os.Remove(tmpName)
304			}
305		}()
306		if _, err = tmp.Write(buf); err != nil {
307			return fmt.Errorf("写入记录文件失败：%w", err)
308		}
309		if err = tmp.Sync(); err != nil {
310			return fmt.Errorf("写入记录文件失败：%w", err)
311		}
312		if err = tmp.Close(); err != nil {
313			return fmt.Errorf("写入记录文件失败：%w", err)
314		}
315		if err = os.Chmod(tmpName, 0o600); err != nil {
316			return fmt.Errorf("设置记录文件权限失败：%w", err)
317		}
318		if err = os.Rename(tmpName, path); err != nil {
319			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
320		}
321		return nil
322	}
