9	// duplicateFieldError 表示同一个 JSON 对象内出现了重复字段名。
10	type duplicateFieldError struct {
11		field string
12	}
13	
14	func (e *duplicateFieldError) Error() string {
15		return fmt.Sprintf("同一 JSON 对象内字段名 %q 重复出现，字段归属无法确定", e.field)
16	}
17	
18	// scanDuplicateKeys 扫描第一份完整 JSON 值的 token 流，在每个对象内检查
19	// 字段名唯一；第一份值之后的字节一律不读（调用方另行检查完整记录之后是否
20	// 还拼接了多余内容，那里的报错信息需要与本检查区分开）。
21	//
22	// 背景：encoding/json 直接解进结构体（或 map）时，同一对象内的重复键会被
23	// 后一个静默覆盖，读不出“曾经写过两个”，因此在正常结构体解码之前先单独
24	// 扫描一遍 token 流。
25	//
26	// 规则：
27	//   - 同一个 JSON 对象内字段名只能出现一次；重复字段是否相邻、两个值是否
28	//     相同都不影响判定，发现即返回 *duplicateFieldError（含字段名）。
29	//   - 比较以 JSON 解码后的文字为准：Token() 返回的键名已完成 Unicode
30	//     反转义，所以直接写出与 \uXXXX 转义形式的同名键仍算重复。
31	//   - 限制只针对同一对象：对象与数组可任意嵌套，数组各元素、不同课程或
32	//     不同学生等不同对象各自携带同名字段是正常结构，互不比较。
33	//   - 字符串“值”里出现字段名（依据、课程名称等）不是键，不参与检查。
34	func scanDuplicateKeys(r io.Reader) error {
35		type frame struct {
36			isObj bool
37			// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
38			// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。
39			// 对象内 token 天然按键、值、键、值交替（逗号不产生 token），
40			// 借此区分字符串 token 是键还是普通字符串值。
41			expectKey bool
42			keys      map[string]struct{}
43		}
44		var stack []frame
45		depth := 0
46	
47		push := func(isObj bool) {
48			f := frame{isObj: isObj}
49			if isObj {
50				f.expectKey = true
51				f.keys = map[string]struct{}{}
52			}
53			stack = append(stack, f)
54		}
55		// valueEnded 通知栈顶对象：刚读完一个值（标量或嵌套结构的结束括号）。
56		valueEnded := func() {
57			if n := len(stack); n > 0 {
58				f := &stack[n-1]
59				if f.isObj && !f.expectKey {
60					f.expectKey = true
61				}
62			}
63		}
64	
65		dec := json.NewDecoder(r)
66		for {
67			tok, err := dec.Token()
68			if err == io.EOF {
69				// 空输入交由后续结构体解码报错（空文件在更前面已被拒绝）。
70				return nil
71			}
72			if err != nil {
73				return err
74			}
75			switch t := tok.(type) {
76			case json.Delim:
77				switch t {
78				case '{':
79					depth++
80					push(true)
81				case '[':
82					depth++
83					push(false)
84				case '}', ']':
85					depth--
86					stack = stack[:len(stack)-1]
87					if depth == 0 {
88						// 唯一的顶层值已完整读完，其后内容不在本检查范围。
89						return nil
90					}
91					// 刚结束的嵌套对象/数组本身就是外层键所对应的值。
92					valueEnded()
93				}
94			case string:
95				n := len(stack)
96				if n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
97					// 对象键：Token() 已按解码后的文字返回。
98					if _, dup := stack[n-1].keys[t]; dup {
99						return &duplicateFieldError{field: t}
100					}
101					stack[n-1].keys[t] = struct{}{}
102					stack[n-1].expectKey = false
103					continue
104				}
105				valueEnded()
106				if depth == 0 {
107					return nil // 顶层标量值
108				}
109			default:
110				// number、bool、nil 等标量值。
111				valueEnded()
112				if depth == 0 {
113					return nil
114				}
115			}
116		}
117	}
