186			t.Fatalf("冲突记录不得输出任何学分核对结果，out=%q", out)
187		}
188		if !strings.Contains(errText, "内容损坏") || !strings.Contains(errText, "w1") ||
189			!strings.Contains(errText, "w2") || !strings.Contains(errText, "r1") {
190			t.Fatalf("错误仍应点名 r1 下冲突的 w1/w2，err=%q", errText)
191		}
192		assertFileByteIdentical(t, file, raw, "带通过修读的冲突文件：")
193	}
